STATE = {'mode': 'fwd', 'dist': 0.0, 'stall': 0.0, 'rt': 0.0}

def control(obs):
    st = STATE
    mot = obs.get('motion', {}) or {}
    v = float(mot.get('v_mps', 0.0) or 0.0)
    hold = float(mot.get('hold_s', 0.0) or 0.0)
    h = float(obs.get('hitch_deg', 0.0) or 0.0)
    dt = float(obs.get('dt', 0.1) or 0.1)
    if hold > 0:
        return (0.0, 0.0, 180)
    if st['mode'] == 'fwd':
        st['dist'] += max(v, 0.0) * dt
        if st['dist'] < 1.5:
            return (0.0, 0.5, 180)
        st['mode'] = 'brk'
        return (0.0, 0.0, 180)
    if st['mode'] == 'brk':
        if abs(v) < 0.05:
            st['mode'] = 'rev'
            st['stall'] = 0.0
            st['rt'] = 0.0
        return (0.0, 0.0, 180)
    # reverse mode: hitch-following toward straight
    if abs(v) < 0.05:
        st['stall'] += dt
    else:
        st['stall'] = 0.0
    if st['stall'] > 1.0:
        st['mode'] = 'fwd'
        st['dist'] = 0.0
        return (0.0, 0.5, 180)
    steer = max(-30.0, min(30.0, 2.0 * h))
    return (steer, -0.3, 180)

